body:
{
  "pains": [
    {
      "id": "pain:cite-check-eats-the-hour",
      "statement": "The draft comes back in two minutes and then somebody has to open every case it cited and confirm the quote is actually in there.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "A research memo or brief section arrives fast, with citations that look right, and some number of them are not real or do not say what the draft claims.",
        "operational": "A person opens each cited case and each quoted line one at a time and confirms it exists and says what the draft says, so the document is still read end to end by hand before it goes anywhere.",
        "personal": "If a bad cite gets through, what the court is told is that this lawyer did not read the case and did not cite check the brief, and that lands on the name on the signature block.",
        "personal_note": "Grounded only in the anonymous firm leader's reputational framing in src:10; no source found shows an individual associate describing what the checking costs them in evenings or in a review, which is why q:pains-personal-cost asks for it."
      },
      "workflow": "The brief or research memo in Word, with the AI output in a separate browser tab, at the step before it goes to the partner where every citation is pulled up one at a time in Westlaw or Lexis and matched against the sentence it was used for.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A filing deadline in a court that has started sanctioning AI-fabricated citations; courts have now addressed hallucinated material in thousands of decisions, so the risk is no longer theoretical.",
          "cites": ["src:5"]
        },
        {
          "event": "Another firm's hallucinated brief becomes public and the firm's own leadership starts asking who is checking what before it is filed.",
          "cites": ["src:10"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "But AI's answer should begin the inquiry, not end it.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Verification means returning to the source and exercising independent professional judgment.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "The hours the tool was supposed to give back go into re-reading the same document against its sources, so the net time saved on a memo is far smaller than the draft time saved.",
          "fears": "That one cite they did not open is the one that is wrong, and it goes out under their name.",
          "dream_outcome": "Output where each line already points at the passage it came from, so checking is reading the passage rather than hunting for it."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Somebody manually has to go and look at every case and every quote, and make sure that it's there.",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "The reputational concern is that it tells the court you didn't read the case and you didn't cite check your brief.",
              "cites": ["src:10"]
            }
          ],
          "costs_them": "They are the person who has to stand up an entire manual review layer behind a tool that was bought to remove manual review.",
          "fears": "That the firm's name ends up in a sanctions order and every AI rollout they argued for gets frozen.",
          "dream_outcome": "A tool whose output can be checked at the speed it is produced, so the verification step stops being a second full pass."
        }
      },
      "segments": ["seg:biglaw", "seg:midsize-firms"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses citation verification. feat:agent is described as reviewing and delivering its own work, which is the model checking itself, not the lawyer being shown where each line came from. This is the largest gap between what the market voices and what the company artifact lists, and the offer and positioning steps should read it as such.",
      "cites": ["src:10", "src:2", "src:5"]
    },
    {
      "id": "pain:the-tools-i-have-barely-work",
      "statement": "The firm is talking about AI while the machine I open every morning cannot keep a few PDFs open, and I am the one losing the hours.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "Programs fail and have to be restarted several times a day, and the laptop stalls on ordinary document work.",
        "operational": "The lawyer restarts, reopens, re-does, and works around the failures, and the firm's newest tool gets judged on the same machine that is already failing.",
        "personal": "The associate reads the cheap hardware as a statement about what the firm thinks they are worth, at a firm that reports a million dollars of revenue per attorney.",
        "personal_note": "Grounded in the associate's own comparison in src:1 between firm revenue per attorney and the equipment issued; no source shows what it costs them at review time."
      },
      "workflow": "The daily run of document work on the firm-issued laptop: several PDFs and a Word document open at once, plus whatever AI tool the firm has added on top, at the step where the programs have to be restarted and the work is done again.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The firm announces an AI rollout while the existing hardware and software have not been fixed, which is the moment the complaint turns from grumbling into a retention question.",
          "cites": ["src:1"]
        },
        {
          "event": "A technology budget round: average firm technology spend rose 41% from 2021 to 2025 and now runs at 5% to 6% of firm revenue, so lawyers can see the money going somewhere other than their desk.",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The outdated technology is borderline unusable and significantly slows down my workflow and severely impedes my efficiency",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Our laptops barely work. The firm should devote more resources to hardware before worrying about AI and technology",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "It's a bad look when a firm that makes a million dollars per attorney is giving its employees the cheapest mouse and keyboard that is offered",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Billable hours lost to restarts and re-work on top of a workload that already runs past normal hours.",
          "fears": "That the firm keeps buying the announceable thing and never fixes the thing they touch every day.",
          "dream_outcome": "Tools that work on the equipment they already have, on the first try, without a workaround."
        }
      },
      "segments": ["seg:biglaw"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company touches this: it is the firm's own estate, not a vendor feature. It matters to this map anyway, because it is the environment any new AI tool lands in and the reason a rollout gets blamed for a slowness that is not its own. Positioning should treat it as a condition of the sale, not a pain to sell against.",
      "cites": ["src:1", "src:4"]
    },
    {
      "id": "pain:legal-is-the-queue",
      "statement": "Sales wants the NDA back today, procurement wants the supplier paper signed, everything in the queue is marked urgent, and there are a handful of us.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "The intake queue is full, every item is flagged urgent, and the business is visibly waiting on legal.",
        "operational": "The team triages by whoever escalates hardest, and routine paper is still read by a lawyer because there is nowhere else for it to go.",
        "personal": "The day is spent deciding which fire to let burn rather than doing the legal work they were hired for.",
        "personal_note": "Grounded in the corporate counsel's own burning-house framing in src:12; no source shows what it costs them outside working hours."
      },
      "workflow": "The legal intake queue and the request threads in Slack at the start of the week, with NDAs, routine renewals and a live master services agreement sitting in the same undifferentiated list, at the step where someone decides by hand which one gets read first.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Growth or a deal push that multiplies contract volume without adding lawyers; nearly half of surveyed in-house respondents already say their legal departments are understaffed.",
          "cites": ["src:17"]
        },
        {
          "event": "Routine paper being moved off the team's plate, which changes the pace of everything else and makes the previous state visible as a bottleneck.",
          "cites": ["src:11"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "If everything is urgent, nothing is urgent.",
              "cites": ["src:12"]
            },
            {
              "situation": "venting",
              "verbatim": "You're in a house and the house is burning. Which room do you go to first?",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "The week goes to triage and routine paper instead of the judgment work only they can do.",
          "fears": "That the one item they deprioritised was the one that mattered, and the business finds out before they do.",
          "dream_outcome": "Routine paper handled without them, and a queue where what is genuinely urgent is visible without reading everything."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "If the honest answer is that this work doesn't deliver value to anybody, then the right allocation is elimination. Not a cheaper resource. Just stop doing that.",
              "cites": ["src:17"]
            },
            {
              "situation": "when_looking",
              "verbatim": "Think about what goes into the white glove bracket, where that extra time is really justified, and what doesn't. And what doesn't should then ideally be moved to self-serve.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Headcount and outside counsel spend go on work that a self-serve path would absorb, and the team still reads as a blocker to the rest of the business.",
          "fears": "That they add lawyers to a queue problem and the queue simply fills again.",
          "dream_outcome": "A clean split between white-glove work the team does and routine work the business serves itself, without legal losing sight of the risk."
        }
      },
      "segments": ["seg:inhouse"],
      "feature_ref": "feat:portal",
      "feature_note": "feat:portal delivers work to clients and collaborators, which is the shape of the self-serve lane the chief legal officer in src:11 is describing. The match is directional rather than proven: no source in this sweep shows an in-house team using Legora's Portal for business self-serve, so the offer step should test it rather than assume it.",
      "cites": ["src:12", "src:11", "src:17"]
    },
    {
      "id": "pain:client-wont-pay-for-what-ai-could-have-done",
      "statement": "The client has decided that anything a chatbot could have produced is not something they are paying for, and that is a real line coming off our bill.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "Clients push back on line items for first-draft research, summarising and routine review.",
        "operational": "The firm writes the time off or reprices the matter, and partners steer around telling clients exactly how the work was produced.",
        "personal": "The partner has to have the conversation with the client about how the work was done, and more than a third of partners say they are uncomfortable having it.",
        "personal_note": "Grounded in the BigHand finding in src:13 that 35% of partners were uncomfortable discussing AI use with clients; no first-person partner quote about that discomfort was found in this sweep."
      },
      "workflow": "The monthly bill review before it goes out, at the line items for first-draft research memos and document review, and then the call with the client's general counsel about what was and was not produced with AI.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A client sets the expectation directly that low-value output a general AI tool could produce is not billable, which firm leadership then has to apply across matters.",
          "cites": ["src:8"]
        },
        {
          "event": "Outside counsel guidelines or a client conversation that forces disclosure of AI use, which 35% of partners say they are uncomfortable having.",
          "cites": ["src:13"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The expectation is if it is something ChatGPT or something else can produce that is low value for the clients, then the expectation is we shouldn't be billing them for it.",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "You must be adding judgment, angle, and know how things affect a business or how it helps them win.",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "Revenue on tasks that used to be billable, at a firm whose cost base was built on those hours being billed.",
          "fears": "That the efficiency gain lands entirely with the client and the firm pays for the tool that caused it.",
          "dream_outcome": "Work the client can see is worth paying for because judgment is visibly in it, priced on the outcome rather than the hour."
        }
      },
      "segments": ["seg:biglaw"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company prices, packages or evidences the work for a client. feat:portal is the closest, since it is what the client sees, but this pain is commercial rather than functional: what would kill it is a way to show the client what judgment went in. Worth naming to the founder as an offer-shaped gap rather than a product one.",
      "cites": ["src:8", "src:13"]
    },
    {
      "id": "pain:activity-isnt-impact",
      "statement": "I can tell you how many contracts we touched and how many people logged in. I cannot tell you what any of it was worth.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "The reporting that exists counts activity: logins, seats activated, matters touched, documents processed.",
        "operational": "The team reports the activity numbers, and the next budget round is argued from anecdote because nothing joins tool usage to an outcome the business recognises.",
        "personal": null,
        "personal_note": "No source in this sweep shows what this costs the individual buyer. The chief legal officer in src:17 and the VP of Legal in src:12 both stop at the reporting problem itself; neither describes a review, a board conversation or a personal consequence. q:pains-personal-cost asks the founder for it."
      },
      "workflow": "The quarterly budget or board review, with the vendor's usage dashboard and the seat count on one side and the department's own matter, cycle-time and spend data on the other, at the step where nobody can join the two into a sentence about value.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The first renewal or budget review after the AI purchase, when the spend has to be defended: average firm technology spend is now 5% to 6% of revenue and no firm in Harbor's 2026 legal lab had a mature framework for measuring AI's business impact.",
          "cites": ["src:4"]
        },
        {
          "event": "Deployment numbers arriving that show tools bought are not in general use, which turns a quiet question into a public one.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "You can't just report on how much onions I chopped up",
              "cites": ["src:17"]
            },
            {
              "situation": "when_looking",
              "verbatim": "You need to take inventory of all the work ingredients that you're doing, and then really right-size what's the best ingredient to really solve that part of the work recipe.",
              "cites": ["src:17"]
            }
          ],
          "costs_them": "Budget they cannot defend and a department that stays a cost line because its output is described in volume rather than in outcomes the business cares about.",
          "fears": "That the spend gets cut at the next review because nobody could name what it changed.",
          "dream_outcome": "Being able to say what the work moved, in the business's own terms, the way the chief legal officer in src:17 reports deal coverage and days off the sales cycle."
        }
      },
      "segments": ["seg:inhouse", "seg:biglaw"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company reports on outcomes. This is listed as one pain across two segments because the buyer voice is in-house (src:17, src:12) while the law firm evidence is analyst and press only (src:4, src:3), which is also why confidence is medium rather than high; q:pains-firm-roi asks whether firm buyers say it in the same words.",
      "cites": ["src:17", "src:12", "src:4", "src:3"]
    },
    {
      "id": "pain:the-slow-part-isnt-the-review",
      "statement": "We keep buying something to make the review faster when what actually holds the contract up happens before it ever reaches me.",
      "element": "b2b:ease_of_doing_business:organization",
      "shape": {
        "surface": "A contract sits for days and the legal review inside it took a fraction of that time.",
        "operational": "The team buys a review tool, review gets faster, cycle time barely moves, and they go looking for the next tool; the handoffs, the missing approvals and the unanswered questions upstream stay exactly where they were.",
        "personal": null,
        "personal_note": "No source shows the personal cost. The legal operations manager in src:11 and the VP of Legal in src:12 both describe the buying mistake from the outside, as advice to others, not as something that cost them something they name."
      },
      "workflow": "The path a contract request takes from the business in Slack through approvals, legal review, signature and the countersigned copy, at the handoffs on either side of the step where a lawyer actually reads the document.",
      "type": "latent",
      "confidence": "medium",
      "revealed_by": "feat:agent",
      "triggers": [
        {
          "event": "A review tool goes in, the review step gets measurably faster, and the end-to-end cycle time does not move, which is the moment the real constraint becomes nameable.",
          "cites": ["src:12"]
        },
        {
          "event": "A staffing conversation: nearly half of surveyed in-house respondents say their departments are understaffed, so the first instinct is to buy speed at the step they can see.",
          "cites": ["src:17"]
        }
      ],
      "who_feels": ["champion", "economic_buyer"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I think one of the misnomers is that people exactly want to go to how do we speed up contracting and how do we use AI to do it. But a lot of the things that slow down contracting actually have nothing to do with contract review at all.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Credibility: they sponsored a tool that did what it promised and did not change the number the business was watching.",
          "fears": "That the department concludes AI does not work here, when what failed was the choice of where to point it.",
          "dream_outcome": "Something that takes a whole request from intake to delivered document, so the measured improvement is cycle time rather than review time."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Do not tool a problem you don't understand.",
              "cites": ["src:12"]
            },
            {
              "situation": "venting",
              "verbatim": "Get in the trenches with the business. They don't care what law school you went to.",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "Budget spent on a tool that optimised a step that was not the constraint, and a second purchase needed to fix the first.",
          "fears": "Buying again into the same misdiagnosis.",
          "dream_outcome": "Knowing where the time actually goes before anything is bought, and buying against that."
        }
      },
      "segments": ["seg:inhouse"],
      "feature_ref": "feat:agent",
      "feature_note": "feat:agent is both what reveals this pain and what would kill it: a feature that plans, executes, reviews and delivers end-to-end work reframes the unit of purchase from the review step to the whole run of work, which is what the legal operations manager in src:11 says the buyer has been getting wrong. It is marked latent because buyers describe the workaround and the mis-buy, not the pain, until they see end-to-end work as an option.",
      "cites": ["src:11", "src:12"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "The market knows AI solutions exist and can name them: 94% of surveyed firms say they are using or exploring generative AI, and the products are discussed by name (Copilot 76%, Claude 44%, CoCounsel 44%, Harvey 43%, Lexis+AI 26%), with Legora at 16%. They know the category and mostly do not know this product.",
      "cites": ["src:3", "src:6"]
    },
    "seg:biglaw": {
      "level": "product",
      "rationale": "At firms of 700 or more lawyers the named products are already in the building: Copilot 88%, Harvey 84%, Claude 64%, Legora 47%, CoCounsel 43%, and Legora sits in pilot or testing at 51% of respondent firms. This segment knows the product and in many cases has not committed to it, which is a product-aware conversation, not a category one.",
      "cites": ["src:3"]
    },
    "seg:midsize-firms": {
      "level": "problem",
      "rationale": "Under 50 lawyers, legal-specific products barely register (Harvey 22%, Legora 6%) while general tools dominate, and firm-level readiness is absent: 54% of firms have provided no training on responsible AI use and have no plans to, and 43% have no formal AI policy and no plans to create one. They feel the problem and are not yet choosing between legal-specific answers.",
      "cites": ["src:3", "src:6"]
    },
    "seg:inhouse": {
      "level": "solution",
      "rationale": "In-house buyers are actively shopping and the recorded advice from their own peers is about buying badly rather than about whether to buy: the guidance is not to tool a problem you do not understand, and to evaluate against what legal is not solving today. That is a segment that knows solutions exist and is choosing among them.",
      "cites": ["src:12", "src:17"]
    }
  },
  "stats": [
    {
      "id": "stat:ai-use-outruns-firm-tooling",
      "stat": "Around seven in ten legal professionals now use generative AI at work, while fewer than half of firms have implemented a tool for them to use.",
      "scope": "Two independent 2026 surveys of legal professionals, both reported by LawSites and Above the Law. 8am's 2026 Legal Industry Report (more than 1,300 legal professionals, surveyed 19 September to 18 October 2025): nearly seven in ten use gen AI, up from 31% a year earlier; only 46% of firms have implemented general-purpose AI tools and 34% have implemented legal-specific ones. Clio's data, reported separately, puts roughly 71% of solos and 75% of small firms already using AI, with almost half of them on generic consumer platforms and more than half operating without any policy. The conservative reading of the gap is used here: individual use is roughly seven in ten, firm provision is under half.",
      "cites": ["src:6", "src:7"]
    },
    {
      "id": "stat:bought-but-not-deployed",
      "stat": "Only two AI products are fully deployed to at least half of a firm's lawyers, and no firm in Harbor's 2026 legal lab had a mature framework for measuring AI's business impact.",
      "scope": "ILTA's 2026 technology survey, over 500 law firms and 140,000 lawyers across a dozen countries: Microsoft Copilot at 52% full deployment among lawyers and Westlaw Advantage at 50% are the only two products past that line, while 94% of firms say they are using or exploring gen AI. Harbor's 2026 legal lab, reported by Above the Law, supplies the measurement half: no participating firm reported a mature framework, against average firm technology spend up 41% from 2021 to 2025 and now 5% to 6% of firm revenue. Two sources, each supplying one half of the claim; neither on its own proves both halves.",
      "cites": ["src:3", "src:4"]
    },
    {
      "id": "stat:hallucination-decisions",
      "stat": "Courts and tribunals have addressed AI-hallucinated material in 2,041 decisions since the second quarter of 2023.",
      "scope": "Damien Charlotin's AI Hallucination Cases database, counted on 2026-09-17 and last updated 2026-09-14: 2,041 decisions globally where a court addressed AI use in more than a passing reference, concentrated in the USA (1,395), Canada (217), Australia (111), Israel (57) and Brazil (41). The count comes from the tracker alone; the second source is a documented 2026 instance at an Am Law firm and corroborates that courts are acting, not the number. Treat the count as one source until a second census is found.",
      "cites": ["src:5", "src:10"]
    },
    {
      "id": "stat:legal-admin-drag",
      "stat": "39% of legal professionals lose four or more productive hours a week to administrative work, and 22% have missed a deadline because of it.",
      "scope": "8am's 2026 Admin Misery Index, companion survey of 400 legal professionals, reported by Above the Law on 2026-08-31: 39% lose four or more productive hours a week (against 44% for the general workforce), 66% say admin interferes with core responsibilities at least some of the time, 22% have missed a deadline because of admin, and 41% put monthly revenue lost to admin at $5,000 or more. The second source is the American Bar Association's 2026 wellbeing survey with Krill Strategies, reported by Artificial Lawyer, which measures the human side of the same load rather than the same number: 47.4% of lawyers screened positive for high burnout and 41% said time in the profession has been detrimental to their mental health. Use the 39% figure and cite the ABA data separately, not as a second count of the same thing.",
      "cites": ["src:9", "src:14"]
    },
    {
      "id": "stat:partners-uncomfortable-discussing-ai",
      "stat": "35% of partners are uncomfortable discussing their AI use with clients.",
      "scope": "BigHand's 2026 Legal Pricing and Budgeting Trends Analysis, reported by Artificial Lawyer on 2026-09-16; sample size not published, which is a reason to quote it carefully. The same survey reports 31% of firms that scrutinised their data found AI improved profitability per matter, 30% saw increased matter throughput and 27% saw a reduction in billable hours for certain tasks. The second source is corroborating voice rather than a second count: the chair of McDermott Will & Schulte stating the client expectation that low-value AI-producible output should not be billed.",
      "cites": ["src:13", "src:8"]
    }
  ],
  "keywords": [
    "cite check AI brief",
    "AI hallucinated cases sanctions",
    "law firm AI policy template",
    "who checks AI output law firm",
    "NDA turnaround time in-house",
    "contract review backlog legal team",
    "legal intake queue triage",
    "self-serve NDA business teams",
    "measure AI ROI law firm",
    "legal department metrics that matter",
    "billing clients for AI work",
    "outside counsel guidelines AI disclosure",
    "contract cycle time not review time",
    "law firm laptop slow PDF",
    "legal ops understaffed"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the first call with the last ten firms and legal teams that bought, what did they say was wrong before you said anything? And what did the ones who did not buy say instead?",
      "why": "Every pain in this map is a hypothesis built from what strangers said unasked. A customer's own first-call sentence is the only evidence class that outranks it, and it would settle which of these six is the one that actually opens a deal.",
      "would_change": "pains[].confidence and the ordering of pains[]; a pain named on the first call by most customers moves to high confidence and the rest move down."
    },
    {
      "id": "q:pains-personal-cost",
      "question": "When a lawyer tells you what checking AI output costs them, what do they actually say it costs? An evening, a review, a conversation with a partner, something else?",
      "why": "The personal rung is what sells and it is the rung no public source gave up. Two of the six pains here have a null personal rung and the other four are inferred from a single reputational or triage line.",
